import { Link } from "react-router-dom";

function AddRole() {
    return (
        <div className="card">
            <div className="card-header">
                <h3 className="card-title">Add New Role</h3>
                <Link to="/roles" className="btn btn-secondary float-right">Back to Roles</Link>
            </div>
        </div>
    )
}
export default AddRole;
